"""
Combine every preceding scientific step into the global reversal design.

End-to-end integration of the paper-derived coefficients and exact recovery channels.

Returns
-------
float scalar E, the dimensionless exact reversal discrepancy for the single globally fitted physical ancilla reset.
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

import numpy as np

def design_reversal(hamiltonians: np.ndarray, bath: np.ndarray, initial_prior: np.ndarray, times: np.ndarray, penalty: float, nominal: np.ndarray, radius: float, z_floor: float) -> float:
    """hamiltonians: complex (N,2*d,2*d) Hermitian array in chronological collision order, N>=1.
    bath: trace-one positive semidefinite complex (2,2) array freshly prepared for each forward collision.
    initial_prior: trace-one positive-definite complex (d,d) array; every evolved prior is positive definite.
    times: nonnegative finite float (N,) array.
    penalty: strictly positive finite real scalar lambda.
    nominal: finite float (3,) Bloch vector ordered X,Y,Z, norm<=1.
    radius: scalar 0<radius<=1; z_floor: scalar -radius<=z_floor<=radius.
    Fit one reset over the exact forward prior trajectory using the second-order local coefficient objective, then compute E from the exact finite-duration channels.
    This final implementation must call and combine all nine preceding public subproblem functions, using their returned coefficients, trajectory, objective, reset, channel maps, and error.
    Every numerical input must be finite. Hermiticity, unit trace, semidefinite positivity, and physical Bloch norm are checked with absolute tolerance 1e-10; positive definiteness and scalar sign bounds are strict.

    Raises
    ------
    ValueError if an input has an invalid shape, a nonfinite value, or violates any documented matrix, state, scalar, or Bloch-vector domain. Real inputs must have zero imaginary part.

    Returns
    -------
    float scalar E, the dimensionless exact reversal discrepancy for the single globally fitted physical ancilla reset.
    """
    return 0.0

# =============================================================================
# GOLD SOLUTION
# =============================================================================

import numpy as np
from scipy.linalg import expm, solve_sylvester
from scipy.optimize import brentq

def _bloch(value, name):
    a = _finite_array(value, name, (3,), real=True)
    if np.linalg.norm(a) > 1 + 1e-10:
        raise ValueError(name + ' must have norm at most one')
    return a

def _bounds(radius, z_floor):
    r = _real_scalar(radius, 'radius', positive=True)
    z = _real_scalar(z_floor, 'z_floor')
    if r > 1 or not -r <= z <= r:
        raise ValueError('Require 0 < radius <= 1 and -radius <= z_floor <= radius')
    return r, z

def _density(value, name, positive_definite=False, dimension=None):
    a = _hermitian(value, name)
    if dimension is not None and a.shape != (dimension, dimension):
        raise ValueError(name + ' has an invalid dimension')
    if abs(np.trace(a) - 1) > 1e-10:
        raise ValueError(name + ' must have unit trace')
    low = np.linalg.eigvalsh(a)[0]
    if (positive_definite and low <= 0) or (not positive_definite and low < -1e-10):
        raise ValueError(name + ' violates its positivity domain')
    return a

def _finite_array(value, name, shape=None, real=False):
    try:
        a = np.asarray(value, dtype=complex)
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError(name + ' must be a numerical array') from exc
    if not np.all(np.isfinite(a)):
        raise ValueError(name + ' must contain finite values')
    if shape is not None and a.shape != shape:
        raise ValueError(name + ' has an invalid shape')
    if real:
        if np.any(a.imag != 0):
            raise ValueError(name + ' must be real')
        a = a.real
    return a

def _hamiltonian(value, dimension=None):
    a = _hermitian(value, 'hamiltonian')
    if a.shape[0] % 2 or (dimension is not None and a.shape != (2*dimension, 2*dimension)):
        raise ValueError('hamiltonian must act on system then qubit ancilla')
    return a

def _hermitian(value, name):
    a = _finite_array(value, name)
    if a.ndim != 2 or a.shape[0] < 1 or a.shape[0] != a.shape[1]:
        raise ValueError(name + ' must be a nonempty square matrix')
    if not np.allclose(a, a.conj().T, atol=1e-10, rtol=0):
        raise ValueError(name + ' must be Hermitian')
    return a

def _real_scalar(value, name, positive=False, nonnegative=False):
    a = _finite_array(value, name, (), real=True)
    x = float(a)
    if (positive and x <= 0) or (nonnegative and x < 0):
        raise ValueError(name + ' violates its sign domain')
    return x

def _sequence_inputs(hamiltonians, bath, initial_prior, times):
    g = _density(initial_prior, 'initial_prior', positive_definite=True)
    xi = _density(bath, 'bath', dimension=2)
    hs = _finite_array(hamiltonians, 'hamiltonians')
    if hs.ndim != 3 or len(hs) < 1 or hs.shape[1:] != (2*len(g), 2*len(g)):
        raise ValueError('hamiltonians has an invalid shape')
    for h in hs:
        _hamiltonian(h, len(g))
    ts = _finite_array(times, 'times', (len(hs),), real=True)
    if np.any(ts < 0):
        raise ValueError('times must be nonnegative')
    return hs, xi, g, ts

def _oracle_design_reversal(hamiltonians,bath,initial_prior,times,penalty,nominal,radius,z_floor):
    try:
        hamiltonians,bath,initial_prior,times=_sequence_inputs(hamiltonians,bath,initial_prior,times)
        penalty=_real_scalar(penalty,'penalty',positive=True);nominal=_bloch(nominal,'nominal')
        radius,z_floor=_bounds(radius,z_floor)
        path=_oracle_prior_trajectory(hamiltonians,bath,initial_prior,times)
        p=[];a=[]
        for k,h in enumerate(hamiltonians):
            c=_oracle_collision_coefficients(h,bath)
            w=_oracle_normalizer_coefficients(path[k],c)
            p.append(_oracle_petz_coefficients(path[k],c,w))
            a.append(_oracle_reverse_coefficients(h))
        obj=_oracle_shared_reset_objective(p,a,times,penalty,nominal)
        s=_oracle_physical_reset(obj,radius,z_floor)
        maps=[_oracle_transition_recovery_maps(h,bath,path[k],path[k+1],times[k],s) for k,h in enumerate(hamiltonians)]
        return _oracle_reversal_error(maps)
    except ValueError as exc:
        raise ValueError('design_reversal: ' + str(exc)) from exc

